namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string DepartmentName { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
    public string Level { get; set; } = ""; // Introductory, Intermediate, Advanced
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public string CourseId { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = "eng", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = "hist", Name = "History", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "CS101", Title = "Introduction to Programming", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, loops, functions, and object-oriented programming basics. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201",
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Bio = "Dr. Lovelace has over 15 years of experience teaching introductory programming. Her research focuses on CS education and curriculum design.", Email = "alovelace@university.edu" },
                IsFeatured = true, Level = "Introductory"
            },
            new()
            {
                Id = "CS301", Title = "Data Structures & Algorithms", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Prerequisite: CS101.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305",
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Professor", Bio = "Dr. Turing is a renowned researcher in theoretical computer science with numerous publications on algorithmic complexity.", Email = "aturing@university.edu" },
                IsFeatured = false, Level = "Intermediate"
            },
            new()
            {
                Id = "CS450", Title = "Machine Learning", DepartmentId = "cs", DepartmentName = "Computer Science",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Prerequisites: CS301, MATH201.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Center 110",
                Instructor = new() { Name = "Dr. Grace Hopper", Title = "Professor", Bio = "Dr. Hopper's research spans AI and distributed systems. She has led multiple NSF-funded projects on applied machine learning.", Email = "ghopper@university.edu" },
                IsFeatured = true, Level = "Advanced"
            },
            new()
            {
                Id = "MATH101", Title = "Calculus I", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 102",
                Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Dr. Noether is an award-winning mathematician specializing in abstract algebra and theoretical physics connections.", Email = "enoether@university.edu" },
                IsFeatured = false, Level = "Introductory"
            },
            new()
            {
                Id = "MATH201", Title = "Linear Algebra", DepartmentId = "math", DepartmentName = "Mathematics",
                Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Essential for advanced study in mathematics, physics, and computer science.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 205",
                Instructor = new() { Name = "Dr. Srinivasa Ramanujan", Title = "Associate Professor", Bio = "Dr. Ramanujan's research explores connections between number theory and linear algebra with applications in cryptography.", Email = "sramanujan@university.edu" },
                IsFeatured = true, Level = "Intermediate"
            },
            new()
            {
                Id = "ENG101", Title = "College Writing", DepartmentId = "eng", DepartmentName = "English",
                Description = "Develop critical reading and academic writing skills. Focus on argumentation, research methods, and clear prose style.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Hall 101",
                Instructor = new() { Name = "Prof. Maya Angelou", Title = "Senior Lecturer", Bio = "Prof. Angelou brings 20 years of experience in composition and rhetoric, with a focus on helping first-year students develop strong writing habits.", Email = "mangelou@university.edu" },
                IsFeatured = false, Level = "Introductory"
            },
            new()
            {
                Id = "ENG350", Title = "Shakespeare Studies", DepartmentId = "eng", DepartmentName = "English",
                Description = "In-depth study of Shakespeare's major plays and sonnets. Explores themes of power, identity, and language in historical and modern contexts.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities Hall 310",
                Instructor = new() { Name = "Dr. Harold Bloom", Title = "Professor", Bio = "Dr. Bloom is a literary scholar specializing in Renaissance drama and the Western literary canon.", Email = "hbloom@university.edu" },
                IsFeatured = false, Level = "Advanced"
            },
            new()
            {
                Id = "PHYS101", Title = "General Physics I", DepartmentId = "phys", DepartmentName = "Physics",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Co-requisite: MATH101.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", Location = "Physics Lab 100",
                Instructor = new() { Name = "Dr. Richard Feynman", Title = "Distinguished Professor", Bio = "Dr. Feynman is celebrated for his engaging lectures and groundbreaking research in quantum electrodynamics.", Email = "rfeynman@university.edu" },
                IsFeatured = true, Level = "Introductory"
            },
            new()
            {
                Id = "PHYS301", Title = "Quantum Mechanics", DepartmentId = "phys", DepartmentName = "Physics",
                Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS101, MATH201.",
                Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Physics Lab 302",
                Instructor = new() { Name = "Dr. Niels Bohr", Title = "Professor", Bio = "Dr. Bohr has published extensively on quantum foundations and atomic structure. He directs the university's quantum research lab.", Email = "nbohr@university.edu" },
                IsFeatured = false, Level = "Advanced"
            },
            new()
            {
                Id = "HIST101", Title = "World History to 1500", DepartmentId = "hist", DepartmentName = "History",
                Description = "Survey of major civilizations, cultures, and events from antiquity through the late medieval period. Emphasis on cross-cultural connections.",
                Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Location = "Liberal Arts 210",
                Instructor = new() { Name = "Dr. Howard Zinn", Title = "Professor", Bio = "Dr. Zinn is a social historian known for inclusive approaches to historical narrative and community-engaged scholarship.", Email = "hzinn@university.edu" },
                IsFeatured = false, Level = "Introductory"
            },
            new()
            {
                Id = "HIST250", Title = "The Modern Era", DepartmentId = "hist", DepartmentName = "History",
                Description = "Explores political, economic, and social transformations from the Enlightenment through the 20th century, including revolutions, industrialization, and globalization.",
                Credits = 3, Schedule = "Tue/Thu 11:30 AM–12:50 PM", Location = "Liberal Arts 215",
                Instructor = new() { Name = "Dr. Eric Hobsbawm", Title = "Associate Professor", Bio = "Dr. Hobsbawm specializes in modern European history and the history of social movements.", Email = "ehobsbawm@university.edu" },
                IsFeatured = false, Level = "Intermediate"
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? departmentId = null, string? search = null, string? level = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(level))
            query = query.Where(c => c.Level.Equals(level, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Id).ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request) =>
        _enrollments.Add(request);
}

