@page "/courses"
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, ID, description, or instructor…" />
    </div>
    <div class="col-md-3">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <select name="level" class="form-select">
            <option value="">All Levels</option>
            <option value="Introductory" selected="@(Level == "Introductory")">Introductory</option>
            <option value="Intermediate" selected="@(Level == "Intermediate")">Intermediate</option>
            <option value="Advanced" selected="@(Level == "Advanced")">Advanced</option>
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = Catalog.GetCourses(Department, Search, Level);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>

    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Course ID</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Level</th>
                <th>Schedule</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td><a href="courses/@course.Id">@course.Id</a></td>
                    <td><a href="courses/@course.Id">@course.Title</a></td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.Level</td>
                    <td>@course.Schedule</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public string? Level { get; set; }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@SubmittedCourse</strong> has been received. You will be notified by email once it has been processed.</p>
        <hr />
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <form method="post" class="col-md-8">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName" class="form-control" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required placeholder="e.g. S12345678" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">— Select a course —</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Id: @course.Title (@course.Credits cr)</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery(Name = "course")] public string? PreselectedCourse { get; set; }

    private bool Submitted;
    private string SubmittedCourse = "";

    protected override void OnInitialized()
    {
        if (!string.IsNullOrEmpty(PreselectedCourse) && string.IsNullOrEmpty(Model.CourseId))
        {
            Model.CourseId = PreselectedCourse;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "")
            && !string.IsNullOrWhiteSpace(Model.StudentName)
            && !string.IsNullOrWhiteSpace(Model.StudentId)
            && !string.IsNullOrWhiteSpace(Model.CourseId))
        {
            var course = Catalog.GetCourse(Model.CourseId);
            SubmittedCourse = course is not null ? $"{course.Id}: {course.Title}" : Model.CourseId;
            Catalog.SubmitEnrollment(Model);
            Submitted = true;
        }
    }

    [CascadingParameter] public HttpContext? HttpContextAccessor { get; set; }
}

